const headers = $input.first().json.payload.headers || [];
const subject = headers.find(h => h.name === 'Subject')?.value || '';
const fromEmail = headers.find(h => h.name === 'From')?.value || '';
const body = $input.first().json.snippet || '';
const messageId = $input.first().json.id;

const emailMatch = fromEmail.match(/<(.+)>/) || [null, fromEmail];
const customerEmail = emailMatch[1] ? emailMatch[1].trim() : fromEmail.trim();

let intent = 'general';
const content = (body + ' ' + subject).toLowerCase();

if (content.includes('order') || content.includes('tracking')) {
  intent = 'order_status';
} else if (content.includes('product') || content.includes('buy')) {
  intent = 'product_inquiry';
} else if (content.includes('problem') || content.includes('issue')) {
  intent = 'technical_support';
}

return [{
  messageId: messageId,
  customerEmail: customerEmail,
  subject: subject,
  body: body,
  intent: intent,
  originalFrom: fromEmail
}];

const orders = $input.all();
const customerData = $node['Email Parser'].json;
const customerEmail = customerData.customerEmail;
const subject = customerData.subject;

let response = 'Hi there!\n\nThank you for contacting us about your order.\n\n';

if (orders.length > 0) {
  const order = orders[0].json;
  response += `Here is your order information:\n\n`;
  response += `Order Number: ${order.name}\n`;
  response += `Status: ${order.fulfillment_status || 'Processing'}\n`;
  response += `Total: ${order.currency} ${order.total_price}\n\n`;

  if (order.fulfillments && order.fulfillments.length > 0) {
    const fulfillment = order.fulfillments[0];
    if (fulfillment.tracking_number) {
      response += `Tracking Number: ${fulfillment.tracking_number}\n`;
      response += `Tracking URL: https://www.dhl.com/track?tracking-id=${fulfillment.tracking_number}\n\n`;
    }
  }
} else {
  response += 'I could not find any orders associated with your email address. Please check that you are contacting us from the same email used for your purchase.\n\n';
}

response += 'If you have any other questions, please let us know!\n\nBest regards,\nCustomer Support';

return [{
  customerEmail: customerEmail,
  subject: `Re: ${subject}`,
  response: response
}];

const products = $input.all();
const customerData = $node['Email Parser'].json;
const customerEmail = customerData.customerEmail;
const subject = customerData.subject;
const emailBody = customerData.body.toLowerCase();

let response = 'Hi there!\n\nThank you for your interest in our products!\n\n';

const relevantProducts = products.filter(item => {
  const product = item.json;
  const title = product.title.toLowerCase();
  return emailBody.split(' ').some(word => 
    word.length > 3 && title.includes(word)
  );
});

if (relevantProducts.length > 0) {
  response += 'Based on your inquiry, here are some products that might interest you:\n\n';
  relevantProducts.slice(0, 3).forEach(item => {
    const product = item.json;
    const price = product.variants && product.variants[0] ? product.variants[0].price : 'Contact for price';
    response += `${product.title}\n`;
    response += `Price: $${price}\n`;
    response += `Link: https://yourstore.myshopify.com/products/${product.handle}\n\n`;
  });
} else {
  response += 'I would be happy to help you find the right product! Could you provide more details about what you are looking for?\n\n';
}

response += 'Feel free to ask if you need more information!\n\nBest regards,\nCustomer Support';

return [{
  customerEmail: customerEmail,
  subject: `Re: ${subject}`,
  response: response
}];

