response += 'If these steps do not resolve the issue, please reply with:\n';
response += '• Detailed description of the problem\n';
response += '• Any error messages\n';
response += '• When the issue started\n\n';
response += 'We are here to help!\n\nBest regards,\nTechnical Support';

return [{
  customerEmail: customerEmail,
  subject: `Re: ${subject}`,
  response: response
}];
